// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        log_ = new LogFile();
        c = new DEP_BANK();
        c.SetMinSum(0);
        c.SetLogFile(address(log_));
    }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, 1 ether, 1000 ether);
        amount = bound(amount, 1, deposit);
        address actor = address(0xBEEF);

        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Deposit{value: deposit}();

        vm.prank(actor);
        c.Collect(amount);

        assertTrue(c.balances(actor) == deposit - amount);
    }
}

contract Collector {
    receive() external payable {}
}
